"""Unified LLM dispatcher.

Routes generation calls to the configured provider based on settings.LLM_PROVIDER.
All agent adapters and routers should use call_llm() / get_default_model()
instead of talking to a provider directly.

Supported providers
-------------------
* ``anthropic`` — Claude via the official ``anthropic`` SDK (AsyncAnthropic).
* ``ollama``    — on-prem via Ollama HTTP API.
* ``openai``    — OpenAI Python SDK; also works with any OpenAI-compatible server
                 (Azure OpenAI, vLLM, Groq, LM Studio, etc.) via OPENAI_BASE_URL.
"""

# Generated by GitHub Copilot

import asyncio
import logging
import time
import random
from pathlib import Path
from typing import Optional, AsyncGenerator, Awaitable, Callable, TypeVar

import httpx

logger = logging.getLogger(__name__)

T = TypeVar("T")


class TransientLLMError(RuntimeError):
    """A retryable LLM failure: connection refused, timeout, 5xx, empty response.

    Distinguished from a plain ``RuntimeError`` (permanent: auth failure, unknown
    model, bad request) so the retry layer knows whether another attempt is worth it.
    """


def _retry_params() -> tuple[int, float, float]:
    """Read retry tuning from settings, tolerating older configs without the keys."""
    from app.core.config import settings
    max_retries = int(getattr(settings, "LLM_MAX_RETRIES", 3) or 0)
    base_delay = float(getattr(settings, "LLM_RETRY_BASE_DELAY", 1.0) or 0.0)
    max_delay = float(getattr(settings, "LLM_RETRY_MAX_DELAY", 10.0) or 0.0)
    return max_retries, base_delay, max_delay


def _is_retryable_status(status_code) -> bool:
    """True for HTTP statuses worth retrying: 429 (rate limit) and 5xx (server)."""
    try:
        code = int(status_code)
    except (TypeError, ValueError):
        return False
    return code == 429 or code >= 500


def _backoff_delay(attempt: int, base_delay: float, max_delay: float) -> float:
    """Exponential backoff with full jitter for retry ``attempt`` (0-indexed)."""
    raw = min(base_delay * (2 ** attempt), max_delay)
    # Full jitter avoids thundering-herd retries when several agents fail at once.
    return random.uniform(0.0, raw)


async def _retry_async(factory: Callable[[], Awaitable[T]], *, what: str) -> T:
    """Run an async LLM call, retrying transient failures with backoff.

    ``factory`` must return a *fresh* awaitable on each call (so each attempt is a
    new request). Permanent errors (non-``TransientLLMError``) propagate immediately.
    """
    max_retries, base_delay, max_delay = _retry_params()
    attempt = 0
    while True:
        try:
            return await factory()
        except TransientLLMError as exc:
            if attempt >= max_retries:
                logger.error("%s failed after %d attempt(s): %s", what, attempt + 1, exc)
                raise
            delay = _backoff_delay(attempt, base_delay, max_delay)
            logger.warning(
                "%s transient error (attempt %d/%d): %s — retrying in %.1fs",
                what, attempt + 1, max_retries + 1, exc, delay,
            )
            await asyncio.sleep(delay)
            attempt += 1


async def _retry_stream(
    factory: Callable[[], AsyncGenerator[str, None]], *, what: str
) -> AsyncGenerator[str, None]:
    """Retry a streaming LLM call, but only while no token has been emitted yet.

    Connection-level failures (the common "all connection attempts failed") happen
    before any token, so retrying is safe. Once tokens have started flowing we must
    NOT restart — that would duplicate already-streamed content — so a mid-stream
    error propagates unchanged.
    """
    max_retries, base_delay, max_delay = _retry_params()
    attempt = 0
    while True:
        produced = False
        try:
            async for token in factory():
                produced = True
                yield token
            return
        except TransientLLMError as exc:
            if produced or attempt >= max_retries:
                if produced:
                    logger.error("%s broke mid-stream — not retrying to avoid duplication: %s", what, exc)
                else:
                    logger.error("%s failed after %d attempt(s): %s", what, attempt + 1, exc)
                raise
            delay = _backoff_delay(attempt, base_delay, max_delay)
            logger.warning(
                "%s transient error (attempt %d/%d): %s — retrying in %.1fs",
                what, attempt + 1, max_retries + 1, exc, delay,
            )
            await asyncio.sleep(delay)
            attempt += 1


def get_default_model() -> str:
    """Return the default model name for the currently configured LLM provider.

    Use this instead of hard-coding ``settings.OLLAMA_MODEL`` in agent code so
    that the correct default is returned regardless of which provider is active.
    """
    from app.core.config import settings  # late import — avoids circular deps

    provider = settings.LLM_PROVIDER.lower()
    if provider == "anthropic":
        return settings.ANTHROPIC_MODEL
    if provider == "openai":
        return settings.OPENAI_MODEL
    return settings.OLLAMA_MODEL


# ---------------------------------------------------------------------------
# Per-agent, provider-aware model resolution (SPEC-023 / T12.3)
# ---------------------------------------------------------------------------

# Prefix → provider namespace. Used to decide whether a model id "belongs" to the
# active provider, so a legacy Ollama value (e.g. seeded in the DB) never gets sent
# to Anthropic/OpenAI as if it were one of their models.
_NAMESPACE_PREFIXES = (
    ("anthropic", ("claude",)),
    ("openai", ("gpt", "o1", "o3", "o4", "chatgpt", "text-")),
)


def _model_namespace(model: str) -> str:
    """Best-effort provider namespace of a model id (defaults to ``ollama``)."""
    m = (model or "").strip().lower()
    for provider, prefixes in _NAMESPACE_PREFIXES:
        if m.startswith(prefixes):
            return provider
    # On-prem tags (mistral:7b, llama3.2:3b, qwen2.5, gemma, phi, …) live here.
    return "ollama"


def _namespace_matches(model: str, provider: str) -> bool:
    return _model_namespace(model) == provider


def _load_agent_frontmatter(agent_name: str) -> dict:
    """Parse the YAML frontmatter of ``<agent_name>.agent.md`` (empty dict if absent).

    La ruta la resuelve `platform/projects/profiles` (T8.4). El import es local
    para no crear un ciclo: el *loader* de proyectos valida capacidades y estas
    acaban importando este módulo.
    """
    from app.platform.projects.profiles import find as find_profile

    filepath = find_profile(agent_name)
    if filepath is None:
        return {}
    try:
        raw = filepath.read_text(encoding="utf-8")
    except Exception:
        return {}
    if raw.startswith("---"):
        parts = raw.split("---", 2)
        if len(parts) >= 3:
            try:
                import yaml
                return yaml.safe_load(parts[1]) or {}
            except Exception:
                return {}
    return {}


def resolve_agent_model(agent_name: str, agent_settings: Optional[dict] = None) -> str:
    """Resolve the model for ``agent_name`` under the active provider (SPEC-023/AC3).

    Cascade, most specific first:

    1. ``agent_settings[agent].model`` — explicit per-run/UI override, honored only
       if its namespace matches the active provider (so a legacy Ollama value
       seeded in the DB doesn't hijack a Claude/OpenAI deployment).
    2. ``.agent.md`` ``models[<provider>]`` — provider-aware per-agent default.
    3. ``.agent.md`` legacy ``model`` — only if its namespace matches the provider.
    4. :func:`get_default_model` — the provider's global default.

    This keeps the per-agent tiering working for Claude *and* Ollama without a
    provider switch silently falling back to a single default for every agent.
    """
    from app.core.config import settings

    provider = settings.LLM_PROVIDER.lower()
    cfg = (agent_settings or {}).get(agent_name, {}) or {}

    # 1. Explicit override (namespace-guarded against stale/legacy values).
    override = cfg.get("model")
    if isinstance(override, str) and override.strip() and _namespace_matches(override, provider):
        return override.strip()

    frontmatter = _load_agent_frontmatter(agent_name)

    # 2. Provider-keyed map from the .agent.md.
    models_map = frontmatter.get("models")
    if isinstance(models_map, dict):
        mapped = models_map.get(provider)
        if isinstance(mapped, str) and mapped.strip():
            return mapped.strip()

    # 3. Legacy single model, only if it belongs to the active provider.
    legacy = frontmatter.get("model")
    if isinstance(legacy, str) and legacy.strip() and _namespace_matches(legacy, provider):
        return legacy.strip()

    # 4. Provider default.
    return get_default_model()


#: Rango que acepta cada proveedor. Anthropic corta en 1.0 y **rechaza** con 400
#: cualquier valor por encima; OpenAI y Ollama llegan a 2.0. Mandar un 1.5 a Claude
#: es el mismo tipo de fallo que mandarle un id de Ollama: la configuración es
#: plausible y el error solo aparece al generar, con el artículo a medias.
TEMPERATURA_MAXIMA = {"anthropic": 1.0, "openai": 2.0, "ollama": 2.0}


def _clamp_temperature(valor: Optional[float], provider: str) -> Optional[float]:
    """Recorta la temperatura al rango del proveedor activo, o `None` si no hay.

    Se recorta **aquí**, en la única puerta a los proveedores, y no en quien la
    resuelve: así protege también a quien llame a `call_llm` directamente —el juez
    de las evals, por ejemplo—. Recortar y no rechazar porque el valor viene de un
    campo de la interfaz sin límites: dejar de generar por una temperatura de 1.2
    sería peor que generar con 1.0.
    """
    if valor is None:
        return None
    try:
        numero = float(valor)
    except (TypeError, ValueError):
        logger.warning("Temperatura no numérica (%r); se usa el default del proveedor.", valor)
        return None

    maximo = TEMPERATURA_MAXIMA.get(provider, 2.0)
    recortado = max(0.0, min(maximo, numero))
    if recortado != numero:
        logger.warning(
            "Temperatura %s fuera del rango de '%s' (0-%s); se recorta a %s.",
            numero, provider, maximo, recortado,
        )
    return recortado


def resolve_agent_temperature(
    agent_name: str, agent_settings: Optional[dict] = None
) -> Optional[float]:
    """Temperatura del agente, o `None` para dejar el default del proveedor.

    Cascada, de lo más específico a lo más general:

    1. ``agent_settings[agent].temperature`` — lo que se eligió para **esta**
       ejecución. El router ya funde ahí el valor del perfil en BD, que es lo que
       edita la interfaz, así que este escalón cubre los dos.
    2. ``.agent.md`` ``temperature`` — para los caminos que no pasan por el router:
       el harness EDD en modo `live`, o una llamada directa al orquestador.
    3. ``None`` — no se envía nada y manda el default del proveedor, que es el
       comportamiento que había antes de conectar esto.

    Espejo de :func:`resolve_agent_model`, a propósito: son el mismo tipo de dato
    —un ajuste por agente que puede venir de tres sitios— y tenerlos con formas
    distintas es lo que hace que uno se quede sin conectar.
    """
    cfg = (agent_settings or {}).get(agent_name, {}) or {}
    valor = cfg.get("temperature")
    if valor is None:
        valor = _load_agent_frontmatter(agent_name).get("temperature")
    if valor is None:
        return None
    try:
        return float(valor)
    except (TypeError, ValueError):
        logger.warning(
            "Temperatura no numérica para '%s' (%r); se usa el default del proveedor.",
            agent_name, valor,
        )
        return None


def _record_usage(provider: str, model: str, entrada, salida) -> None:
    """Anotar tokens consumidos (SPEC-019/T5.2 y SPEC-014/T9.1).

    Se llama desde cada proveedor porque es el único sitio donde se conocen: la
    respuesta de la API los trae, y `call_llm` solo ve el texto ya extraído.
    Van a dos sitios con propósitos distintos: a las métricas, que son agregadas y
    operativas, y a la traza del paso en curso, que es por ejecución y sirve para
    explicar **esta** ejecución.

    Nunca lanza — medir no puede tumbar una generación.
    """
    try:
        from app.platform.metrics import observe_llm_tokens

        observe_llm_tokens(
            provider=provider, model=model,
            input_tokens=int(entrada or 0) or None,
            output_tokens=int(salida or 0) or None,
        )
    except Exception:  # pragma: no cover - defensivo
        pass
    try:
        from app.platform.explainability import record_tokens

        record_tokens(entrada, salida)
    except Exception:  # pragma: no cover - defensivo
        pass


async def call_llm(
    prompt: str,
    *,
    model: Optional[str] = None,
    timeout: float = 60.0,
    system_prompt: Optional[str] = None,
    keep_alive: int = -1,
    num_ctx: Optional[int] = None,
    temperature: Optional[float] = None,
) -> str:
    """Call the configured LLM provider and return the generated text.

    Args:
        prompt: The user / task prompt.
        model: Model override. ``None`` uses the provider's configured default.
        timeout: HTTP / SDK request timeout in seconds.
        system_prompt: Optional system message (used only with OpenAI Chat API).
        keep_alive: Ollama keep-alive seconds. Use 0 to unload the model
            immediately after the call (frees VRAM/RAM). -1 = Ollama default.
        num_ctx: Override the model context window size. Smaller values
            reduce KV-cache RAM. ``None`` uses the model's default.
        temperature: Sampling temperature. ``None`` (default) sends nothing and
            leaves the provider's own default in place, so existing callers are
            unaffected. Added for the EDD judge (SPEC-014/T9.4), which the spec
            requires to run at ``temperature=0``: a judge that changes its mind
            between runs turns the T9.5 gate into a random red-light generator,
            because the metric stops measuring the agent and starts measuring
            the judge.

    Returns:
        The generated text, stripped of leading/trailing whitespace.

    Raises:
        RuntimeError: On any network, API or parsing error.
    """
    from app.core.config import settings
    from app.platform.metrics import observe_llm_call

    provider = settings.LLM_PROVIDER.lower()
    resolved_model = model or get_default_model()
    temperature = _clamp_temperature(temperature, provider)
    _inicio = time.perf_counter()

    async def _medido(coro_factory):
        """Cronometra la llamada y anota el resultado (SPEC-019/T5.2).

        Envuelve el dispatcher entero para que la latencia incluya los reintentos:
        es lo que de verdad espera quien llama, y un proveedor que solo responde al
        tercer intento tiene que verse lento, no sano.
        """
        estado = "error"
        try:
            resultado = await coro_factory()
            estado = "ok"
            return resultado
        finally:
            observe_llm_call(
                provider=provider, model=resolved_model,
                duration=time.perf_counter() - _inicio, status=estado,
            )

    if provider == "anthropic":
        return await _medido(lambda: _retry_async(
            lambda: _call_anthropic(
                prompt=prompt,
                model=resolved_model,
                timeout=timeout,
                system_prompt=system_prompt,
                temperature=temperature,
            ),
            what=f"Anthropic call ({resolved_model})",
        ))

    if provider == "openai":
        return await _medido(lambda: _retry_async(
            lambda: _call_openai(
                prompt=prompt,
                model=resolved_model,
                timeout=timeout,
                system_prompt=system_prompt,
                temperature=temperature,
            ),
            what=f"OpenAI call ({resolved_model})",
        ))

    # Default: Ollama
    return await _medido(lambda: _retry_async(
        lambda: _call_ollama(
            prompt=prompt,
            model=resolved_model,
            timeout=timeout,
            keep_alive=keep_alive,
            num_ctx=num_ctx,
            temperature=temperature,
        ),
        what=f"Ollama call ({resolved_model})",
    ))


async def call_llm_stream(
    prompt: str,
    *,
    model: Optional[str] = None,
    timeout: float = 60.0,
    system_prompt: Optional[str] = None,
    keep_alive: int = -1,
    num_ctx: Optional[int] = None,
    temperature: Optional[float] = None,
) -> AsyncGenerator[str, None]:
    """Call the configured LLM provider and yield the generated tokens.

    ``temperature``: igual que en :func:`call_llm`. Va también aquí porque el
    redactor —el agente cuya temperatura más se nota— genera por streaming: sin
    esto, el único agente que escribe el artículo se habría quedado fuera.
    """
    from app.core.config import settings

    provider = settings.LLM_PROVIDER.lower()
    resolved_model = model or get_default_model()
    temperature = _clamp_temperature(temperature, provider)

    if provider == "anthropic":
        stream_factory = lambda: _call_anthropic_stream(
            prompt=prompt,
            model=resolved_model,
            timeout=timeout,
            system_prompt=system_prompt,
            temperature=temperature,
        )
        what = f"Anthropic stream ({resolved_model})"
    elif provider == "openai":
        stream_factory = lambda: _call_openai_stream(
            prompt=prompt,
            model=resolved_model,
            timeout=timeout,
            system_prompt=system_prompt,
            temperature=temperature,
        )
        what = f"OpenAI stream ({resolved_model})"
    else:
        stream_factory = lambda: _call_ollama_stream(
            prompt=prompt,
            model=resolved_model,
            timeout=timeout,
            keep_alive=keep_alive,
            num_ctx=num_ctx,
            temperature=temperature,
        )
        what = f"Ollama stream ({resolved_model})"

    async for token in _retry_stream(stream_factory, what=what):
        yield token


